# R/utils_techdesign_catalog_zsocial.R
# ============================================================
# TECHNICAL DESIGNS - Social Dynamics Algorithms (top 36)
# Distilled from: Games People Play (Berne), How to Win Friends and Influence People (Carnegie),
# Influence (Cialdini), Getting to Yes (Fisher, Ury), Thinking in Bets (Duke), Algorithms to Live By
# (Christian, Griffiths), How Life Imitates Chess (Kasparov), Captivate (Van Edwards), The Rational Male
# (Tomassi), The Game (Strauss), the film Limitless and the series Elementary (Sherlock / Joan Watson).
# Each algorithm is a compact spec; social_build_text() turns it into the standard design text for one audience,
# so it is parsed and drawn by the same renderer as every other design (no API or BigQuery needed to view it).
# Sorts after utils_techdesign_catalog.R (Shiny autoload is alphabetical).
# These are concept-level summaries in my own words, not quotations.
# ============================================================

SOC_AUDIENCES <- c(I = "Influencing people", R = "Romantic partners", B = "Business partners", V = "Investors", C = "Collaborators")

# helper: one algorithm spec
.sp <- function(id, label, src, aud, summary, when, avoid, input, state, steps, check, fix, out, guard, pitfall, app) {
  list(id = id, label = label, src = src, aud = strsplit(aud, "")[[1]], summary = summary, when = when, avoid = avoid, input = input,
       state = state, steps = steps, check = check, fix = fix, out = out, guard = guard, pitfall = pitfall, app = app)
}

