# ---- builder: spec + audience -> standard design text -------------------------------------
.sc <- function(x) gsub("\\s+", " ", gsub("[][\"\\\\$]", "", gsub("\r|\n", " ", as.character(x))))
social_build_text <- function(sp, aud) {
  ap <- unname(sp$app[aud]); if (length(ap) == 0 || is.na(ap)) ap <- sp$summary
  aud_lab <- SOC_AUDIENCES[[aud]]
  st <- sp$steps
  comp <- function(id, label, lane, kind, desc, tech = "N/A") paste0("@component\nid: ", id, "\nlabel: ", .sc(label), "\nlane: ", lane, "\nkind: ", kind, "\ndescription: ", .sc(desc), "\ntechnologies: ", .sc(tech), "\n")
  conn <- function(from, to, label, type) paste0("@connection\nfrom: ", from, "\nto: ", to, "\nlabel: ", .sc(label), "\ntype: ", type, "\n")
  short <- function(x, n = 38) { x <- .sc(x); if (nchar(x) > n) paste0(substr(x, 1, n - 3), "...") else x }
  parts <- c(
    paste0("design_group: social_dynamics\ndesign_type: ", sp$id, "\ntitle: ", .sc(sp$label), " - ", aud_lab, "\nvariant: ", aud_lab,
           "\nsummary: ", .sc(paste(sp$summary, "Use with", tolower(aud_lab), ":", ap)), "\nwhen_to_use: ", .sc(sp$when), "\nwhen_not_to_use: ", .sc(sp$avoid),
           "\ncomplexity: Medium\ntags: ", .sc(paste0(sp$src, ", ", aud_lab)), "\n"),
    comp("C1", "Situation", "Input", "actor", sp$input, aud_lab),
    comp("C2", "Signals and state", "Signals and State", "store", sp$state),
    comp("C3", short(st[1], 30), "Procedure", "process", st[1]),
    comp("C4", short(st[2], 30), "Procedure", "process", st[2]),
    comp("C5", short(st[3], 30), "Procedure", "process", st[3]),
    comp("C6", short(st[4], 30), "Check and Act", "process", st[4]),
    comp("C7", short(sp$check, 30), "Check and Act", "gateway", paste("Decision point:", sp$check)),
    comp("C8", short(st[5], 30), "Check and Act", "process", st[5]),
    comp("C9", short(sp$out, 30), "Outcome", "external", sp$out),
    comp("C10", "Ethical guardrail", "Outcome", "monitor", sp$guard),
    conn("C1", "C3", "start", "data"), conn("C2", "C3", "context", "data"), conn("C3", "C4", "next", "data"), conn("C4", "C5", "next", "data"),
    conn("C5", "C6", "act", "data"), conn("C6", "C7", "evaluate", "control"), conn("C7", "C8", "yes", "event"), conn("C8", "C9", "result", "data"),
    conn("C7", "C5", short(sp$fix, 28), "feedback"), conn("C10", "C6", "constrains", "control"), conn("C9", "C2", "update state", "feedback"),
    paste0("@step\norder: 1\ntext: ", .sc(paste("Situation for", tolower(aud_lab), ":", ap)), "\ncomponents: C1, C2\n"),
    paste0("@step\norder: 2\ntext: ", .sc(st[1]), "\ncomponents: C3\n"),
    paste0("@step\norder: 3\ntext: ", .sc(st[2]), "\ncomponents: C4\n"),
    paste0("@step\norder: 4\ntext: ", .sc(st[3]), "\ncomponents: C5\n"),
    paste0("@step\norder: 5\ntext: ", .sc(st[4]), "\ncomponents: C6, C10\n"),
    paste0("@step\norder: 6\ntext: ", .sc(paste0(sp$check, " If not: ", sp$fix, ".")), "\ncomponents: C7, C5\n"),
    paste0("@step\norder: 7\ntext: ", .sc(paste(st[5], "->", sp$out)), "\ncomponents: C8, C9, C2\n"),
    paste0("@tradeoff\nkind: pro\ntext: ", .sc(ap), "\n"),
    paste0("@tradeoff\nkind: con\ntext: ", .sc(sp$pitfall), "\n"),
    paste0("@tradeoff\nkind: risk\ntext: ", .sc(sp$guard), "\n"),
    paste0("@tradeoff\nkind: cost\ntext: ", .sc(paste("Do not use when:", sp$avoid)), "\n"),
    paste0("@reference\ntitle: ", .sc(sp$src), "\nauthor: N/A\nurl: N/A\n")
  )
  paste(parts, collapse = "\n")
}

social_specs_for <- function(aud) Filter(function(s) aud %in% s$aud, SOC_SPECS)
social_spec <- function(id) { i <- which(vapply(SOC_SPECS, function(s) s$id == id, TRUE)); if (length(i)) SOC_SPECS[[i[1]]] else NULL }

# catalog entry per algorithm so Guide / Library / Recommender helpers know them
TD_CATALOG$social_dynamics <- setNames(lapply(SOC_SPECS, function(s) list(label = s$label, guidance = paste0("\nDESIGN = social dynamics algorithm from ", s$src, ". ", s$summary, "\n"))), vapply(SOC_SPECS, function(s) s$id, ""))

# whole top-32 as a Markdown research report
social_report_md <- function() {
  out <- c("# Top 36 Social Dynamics Algorithms", "",
           "Distilled from: Games People Play, How to Win Friends and Influence People, Influence, Getting to Yes, Thinking in Bets, Algorithms to Live By, How Life Imitates Chess, Captivate, The Rational Male, The Game, the film Limitless and the series Elementary. Concept-level summaries in plain words. Four start-up funding algorithms (33-36) cover narrative, traction proof, fundraising sprint and investor fit.", "",
           "Ethical rule for all of them: honest intent, mutual benefit, consent, and no deception. Techniques that only work by tricking people are flagged.", "")
  for (i in seq_along(SOC_SPECS)) {
    s <- SOC_SPECS[[i]]
    out <- c(out, sprintf("## %d. %s", i, s$label), sprintf("**Source:** %s  \n**Audiences:** %s", s$src, paste(SOC_AUDIENCES[s$aud], collapse = ", ")), "", s$summary, "",
             sprintf("**Use when:** %s  \n**Avoid when:** %s", s$when, s$avoid), "", "**Procedure:**", paste0(seq_along(s$steps), ". ", s$steps),
             sprintf("\n**Check:** %s -> otherwise: %s  \n**Outcome:** %s", s$check, s$fix, s$out), "", "**By audience:**",
             paste0("- ", SOC_AUDIENCES[names(s$app)], ": ", s$app), "", sprintf("**Guardrail:** %s  \n**Pitfall:** %s", s$guard, s$pitfall), "")
  }
  out <- c(out, "## Sources", paste0("- ", gsub(" \\| ", " - ", SOC_BOOK_REFS)))
  paste(out, collapse = "\n")
}
